 function tables(r){const table=(head,rows)=>`<table><thead><tr>${head.map(v=>`<th>${escape(v)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${escape(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
  return '<h3>Applied loads · joint transfer audit</h3><p class="help">Transferred loads are superposed once with manual nodal forces. They preserve the force and moment of the specified path loading; no local member bending is calculated.</p>'+table(['Node','Manual Fx (N)','Manual Fy (N)','Transfer Fx (N)','Transfer Fy (N)','Total Fx (N)','Total Fy (N)'],r.nodes.map((n,i)=>[n.id,fmt(r.model.nodes[i].fx),fmt(r.model.nodes[i].fy),fmt(r.distributed.nodes[i].fx),fmt(r.distributed.nodes[i].fy),fmt(n.fx),fmt(n.fy)]))+'<h3>Members · positive = tension; negative = compression</h3>'+table(['Member','Nodes','Type / state','Force (N)','Stress (MPa)','Joint separation change (mm)','Elastic extension (mm)'],r.members.map((m,i)=>[i+1,`${m.a}–${m.b}`,m.cableState??'bar',fmt(m.force),fmt(m.stress),fmt(m.extension),fmt(m.elasticExtension)]))+'<h3>Euler member-buckling screening</h3><p class="help">Elastic, straight slender member; weakest-axis Imin and effective length K L. This is a member check, not global truss eigenvalue buckling or a post-buckling solution. Unspecified I is NOT a pass.</p>'+table(['Member','Pcr (N)','KL/r','Compression / Pcr','Check'],r.members.map((m,i)=>[i+1,m.Pcr===null?'—':fmt(m.Pcr),m.slenderness===null?'—':fmt(m.slenderness),m.utilization===null?'—':fmt(m.utilization),m.type==='cable'?'Wire: no compression':m.Imin===null?'NOT CHECKED: enter Imin':m.force>=0?'No compression in this case':m.utilization>=1?'AT/ABOVE EULER LIMIT: linear result not a safe capacity': 'Below elastic Euler load (other failure checks required)']))+'<h3>Nodes · global +x right, +y up</h3>'+table(['Node','ux (mm)','uy (mm)','Rx (N)','Ry (N)'],r.nodes.map(n=>[n.id,fmt(n.ux),fmt(n.uy),fmt(n.rx),fmt(n.ry)]));
 }
 $('#solve').onclick=()=>attempt(()=>{result=null;$('#csv').disabled=true;$('#results').innerHTML='';$('#resultSummary').textContent='No current result.';draw();const r=T.solve(model);result=r;$('#csv').disabled=false;$('#results').innerHTML=tables(r);$('#resultSummary').textContent=`Maximum displacement ${fmt(r.maxDisplacement)} mm. Slack wires: ${r.slackCables}. Global equilibrium residuals: ΣFx=${fmt(r.equilibrium.fx)} N; ΣFy=${fmt(r.equilibrium.fy)} N; ΣM=${fmt(r.equilibrium.m)} N·mm.`;const lengths=r.members.map(m=>m.L),buckled=r.members.some(m=>m.utilization>=1),large=r.maxDisplacement>.05*Math.min(...lengths);status(buckled?'Euler limit reached/exceeded. Displayed linear displacements do NOT model buckling or post-buckling.':large?'Solved, but displacement exceeds 5% of the shortest member: small-displacement results may be inappropriate.':`Solved. Tension blue; compression orange; slack wires faint/dashed. Euler checked only where Imin is supplied. ${r.members.filter(m=>m.type==='bar'&&m.Imin===null).length} bars not checked.`,buckled||large);draw();});
 function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 $('#image').onclick=()=>download($('#trussCanvas').innerHTML,'image/svg+xml','truss-model.svg');
 $('#csv').onclick=()=>{if(!result)return;const rows=[['member','node_a','node_b','type','wire_state','force_N_tension_positive','stress_MPa','joint_separation_change_mm','elastic_extension_mm','Euler_Pcr_N','compression_over_Pcr','KL_over_r'],...result.members.map((m,i)=>[i+1,m.a,m.b,m.type,m.cableState??'',m.force,m.stress,m.extension,m.elasticExtension,m.Pcr??'',m.utilization??'',m.slenderness??'']),[],['node','ux_mm','uy_mm','Rx_N_right_positive','Ry_N_up_positive'],...result.nodes.map(n=>[n.id,n.ux,n.uy,n.rx,n.ry])];rows.push([],['applied_node','manual_Fx_N','manual_Fy_N','transfer_Fx_N','transfer_Fy_N','total_Fx_N','total_Fy_N'],...result.nodes.map((n,i)=>[n.id,result.model.nodes[i].fx,result.model.nodes[i].fy,result.distributed.nodes[i].fx,result.distributed.nodes[i].fy,n.fx,n.fy]),[],['line_load','ordered_nodes','q_start_N_per_mm','q_end_N_per_mm','angle_deg_CCW'],...result.model.lineLoads.map((v,i)=>[i+1,v.nodes.join(';'),v.qStart,v.qEnd,v.angle]));download(rows.map(r=>r.join(',')).join('\n'),'text/csv','truss-results.csv');};
 $('#example').onclick=()=>{if(model.nodes.length&&!confirm('Replace the current model with the optional braced bay?'))return;model={nodes:[{id:1,x:0,y:0,support:'pin',fx:0,fy:0},{id:2,x:1000,y:0,support:'rollerY',fx:0,fy:0},{id:3,x:0,y:400,support:'free',fx:0,fy:50},{id:4,x:1000,y:400,support:'free',fx:0,fy:50}],members:[[1,2],[1,3],[2,4],[3,4],[1,4]].map(([a,b])=>({a,b,E:70000,A:100}))};selected=null;first=null;dirty();selection();fit();status('Optional generic braced bay loaded with two +50 N nodal forces. Not a historical aircraft model. Press Solve.');};
 const wireExample=document.createElement('button');wireExample.id='wireExample';wireExample.textContent='Load crossed-wire bay';$('#example').after(wireExample);
 wireExample.onclick=()=>{if(model.nodes.length&&!confirm('Replace the current model with an illustrative crossed-wire bay?'))return;
  model={nodes:[{id:1,x:0,y:0,support:'pin',fx:0,fy:0},{id:2,x:1000,y:0,support:'rollerY',fx:0,fy:0},{id:3,x:0,y:400,support:'free',fx:0,fy:0},{id:4,x:1000,y:400,support:'free',fx:20,fy:0}],members:[[1,2],[1,3],[2,4],[3,4]].map(([a,b])=>({a,b,type:'bar',E:70000,A:100,Imin:10000/12,Kfactor:1})).concat([[1,4],[2,3]].map(([a,b])=>({a,b,type:'cable',E:200000,A:2,Imin:null,Kfactor:1})))};
  selected=null;first=null;dirty();selection();fit();status('Illustrative crossed-wire bay: 20 N right at N4. Bars: E=70000 MPa, 10×10 mm square; wires: E=200000 MPa, A=2 mm². Invented teaching data, not Wright aircraft measurements. Reverse N4 Fx to see the other wire engage. Press Solve.');
 };
 for(const kind of ['pin','roller']){const button=$('[data-tool="'+kind+'"]'),activate=button.onclick;button.onclick=()=>{const wasOpen=!$('#'+kind+'Menu').hidden;activate();closeSupportMenus();$('#'+kind+'Menu').hidden=wasOpen;button.setAttribute('aria-expanded',String(!wasOpen));};}
 window.TrussLab={state:()=>JSON.parse(JSON.stringify({model,result,selected,tool,historyIndex,historyLength:history.length})),undo:()=>travel(-1),redo:()=>travel(1),snapPoint:snapped,setModel:m=>{model=T.normalize(m);selected=null;dirty();selection();fit();}};stabilityPanel();draw();
